import 'dart:io';

/// Test images generated by `tool/make_image_fixtures.py`. All are 40x30 as
/// stored; orientation 6 and 8 display as 30x40.
File fixtureImage(String name) => File('test/fixtures/images/$name');

/// Copies a fixture into [dir] as a fresh "picked" temp file.
File copyFixture(String name, Directory dir, [String? as]) =>
    fixtureImage(name).copySync('${dir.path}/${as ?? name}');
